/**
 * Retourne le markup SVG inline pour une icône PR-Front.
 * @param {string} name
 * @param {{size?:number,cls?:string,color?:string}} [opts]
 */
function prfIcon(name, opts = {}) {
  const { size = 18, cls = "", color } = opts;
  const def = ICONS[name];
  if (def == null) return "";
  const stroke = def.stroke ?? DEFAULT_STROKE;
  const viewBox = def.viewBox ?? "0 0 24 24";
  const fillColor = def.fillColor ?? "currentColor";

  let attrs = `width="${size}" height="${size}" viewBox="${viewBox}" class="prf-icon${cls ? " " + cls : ""}"`;
  attrs += ` fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round"`;
  attrs += ` aria-hidden="true" focusable="false"`;
  if (color) attrs += ` style="color:${color}"`;

  const paths = def.paths
    .map((p) => {
      if (p.fill) {
        return `<path d="${p.d}" fill="${fillColor}" stroke="none"/>`;
      }
      const w = p.width ?? stroke;
      return `<path d="${p.d}" stroke-width="${w}"/>`;
    })
    .join("");

  return `<svg xmlns="http://www.w3.org/2000/svg" ${attrs}>${paths}</svg>`;
}

/** Hydrate tous les <i data-prf-icon> non encore traités dans `root`. */
function hydratePrfIcons(root = document) {
  if (!root || typeof root.querySelectorAll !== "function") return;
  const nodes = root.querySelectorAll("[data-prf-icon]:not([data-prf-icon-done])");
  nodes.forEach((el) => {
    const name = el.getAttribute("data-prf-icon");
    const size = Number(el.getAttribute("data-prf-icon-size")) || 18;
    const color = el.getAttribute("data-prf-icon-color");
    el.innerHTML = prfIcon(name, { size, color });
    el.classList.add("prf-icon-wrap");
    el.setAttribute("data-prf-icon-done", "1");
  });
}

// Exposition globale (pour tournois.js classique)
if (typeof window !== "undefined") {
  window.PRF_ICONS = ICONS;
  window.prfIcon = prfIcon;
  window.hydratePrfIcons = hydratePrfIcons;
}

// Auto-hydratation + observation du DOM (comme icons.js)
if (typeof document !== "undefined") {
  const boot = () => hydratePrfIcons(document);
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
  let _debounce = null;
  const observer = new MutationObserver(() => {
    if (_debounce) return;
    _debounce = requestAnimationFrame(() => {
      _debounce = null;
      hydratePrfIcons(document);
    });
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });
}

export { ICONS, prfIcon, hydratePrfIcons };
